ALTER TABLE "commercial_billing_orders" ADD CONSTRAINT "commercial_billing_orders_creator_shape" CHECK (("commercial_billing_orders"."provider_code" = 'manual-bank-transfer' AND "commercial_billing_orders"."created_by_user_id" IS NULL AND "commercial_billing_orders"."created_by_operator" IS NOT NULL AND length(btrim("commercial_billing_orders"."created_by_operator")) BETWEEN 1 AND 200 AND "commercial_billing_orders"."creation_reason" IS NOT NULL AND length(btrim("commercial_billing_orders"."creation_reason")) BETWEEN 12 AND 500 AND "commercial_billing_orders"."manual_idempotency_key" IS NOT NULL AND length(btrim("commercial_billing_orders"."manual_idempotency_key")) BETWEEN 8 AND 128) OR ("commercial_billing_orders"."provider_code" <> 'manual-bank-transfer' AND "commercial_billing_orders"."created_by_user_id" IS NOT NULL AND "commercial_billing_orders"."created_by_operator" IS NULL AND "commercial_billing_orders"."creation_reason" IS NULL AND "commercial_billing_orders"."manual_idempotency_key" IS NULL));
